import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('clinica.db');
db.exec(`CREATE TABLE IF NOT EXISTS usuarios (
  id INTEGER PRIMARY KEY,
  email TEXT NOT NULL,
  senha TEXT NOT NULL
)`);

db.prepare('INSERT INTO usuarios (email, senha) VALUES (?, ?)')
  .run('ana@clinica.com', '123');

// ERRADO — o texto digitado é colado no comando (a injeção mora aqui)
function loginInseguro(email, senha) {
  const sql = `SELECT * FROM usuarios
               WHERE email = '${email}' AND senha = '${senha}'`;
  return db.prepare(sql).get();
}

// CERTO — comando fixo, valores por parâmetro (?)
const loginSeguro = db.prepare(
  'SELECT * FROM usuarios WHERE email = ? AND senha = ?',
);

// O atacante digita: ' OR '1'='1
// - loginInseguro: WHERE email = '' OR '1'='1' AND senha = 'x' → verdadeiro!
// - loginSeguro: procura o e-mail literal "' OR '1'='1" → undefined (ninguém)
console.log(loginSeguro.get("' OR '1'='1", 'x'));
// undefined — as aspas do atacante ficaram DENTRO do valor, não do comando

import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('clinica.db');

db.exec(`CREATE TABLE IF NOT EXISTS pacientes (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL
)`);

db.prepare('INSERT INTO pacientes (nome) VALUES (?), (?), (?)')
  .run('Ana', 'Beto', 'Caio');

// Camada 1 — parâmetros: o termo digitado é um VALOR, nunca SQL.
// O padrão LIKE com % busca "contém", mas os % são do COMANDO,
// fixos; o que o usuário digitar não ganha poder nenhum.
const buscarPorNome = db.prepare(
  'SELECT * FROM pacientes WHERE nome LIKE ?',
);

// Camada 2 — validação: entrada estranha para antes do banco.
// (o parâmetro já protegeria; isto é defesa em profundidade, não substituto)
function buscarPacientes(termo) {
  if (typeof termo !== 'string' || termo.length > 50) {
    throw new Error('termo de busca inválido');
  }
  return buscarPorNome.all(`%${termo}%`);
}

console.log(buscarPacientes('an')); // [ { id: 1, nome: 'Ana' } ]

// O golpe: ' OR '1'='1' --  entra como TEXTO de busca.
// Com parâmetro, o banco procura pacientes cujo nome contém essa
// frase literal. Ninguém se chama assim: devolve lista vazia.
console.log(buscarPacientes("' OR '1'='1' --"));
// []
